const ids=["vltx-factsheet","vltx-options-note","cma-minutes-oct","cma-speech-ashby"];
const d=await Promise.all(ids.map(i=>world.doc(i)));
const s=await Promise.all(["vltx_iv","vltx_rv","cma_futures"].map(n=>world.series(n)));
return {d:d.map(x=>x.body),s:s.map(x=>({n:x.name,u:x.unit,p:JSON.stringify(x.points).slice(0,1500)}))};

